import './ambient-pursuits.js';
import * as THREE from './vendor/three.module.js';
import {ModernGameplay} from './modern-gameplay.js';
import {dist,project,roadRoute} from './core.js';
import {followRoad} from './chase-routing.js';

const COURSE_KEY='padova-bike-records-v1';
const COURSES=[
 {id:'euganeo',name:'Euganeo Slalom',start:project(45.4352,11.8564),end:project(45.4298,11.8668)},
 {id:'zona-est',name:'Zona Est Sprint',start:project(45.4104,11.9390),end:project(45.4054,11.9528)},
 {id:'arcella',name:'Arcella Switchback',start:project(45.4352,11.8825),end:project(45.4430,11.8885)},
 {id:'sud',name:'Sud / Albignasego Run',start:project(45.3748,11.8695),end:project(45.3843,11.8756)}
];
let activeGame=null,challenge=null,courseRoot=null,startRoots=[],streetRacer=null,nextRacerAt=0;
const materialCache=new Map();
function mat(color){if(!materialCache.has(color))materialCache.set(color,new THREE.MeshStandardMaterial({color,roughness:.82}));return materialCache.get(color);}
function box(root,color,x,y,z,w,h,d){const mesh=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat(color));mesh.position.set(x,y,z);mesh.receiveShadow=true;root.add(mesh);return mesh;}
function records(){try{return JSON.parse(localStorage.getItem(COURSE_KEY)||'{}');}catch{return {};}}
function saveRecord(id,time){const data=records(),old=Number(data[id]);if(!Number.isFinite(old)||time<old){data[id]=Number(time.toFixed(3));try{localStorage.setItem(COURSE_KEY,JSON.stringify(data));}catch{}return true;}return false;}
function formatTime(seconds){if(!Number.isFinite(seconds))return '—';const m=Math.floor(seconds/60),s=seconds-m*60;return m+':'+s.toFixed(2).padStart(5,'0');}
function isBike(state){const c=state.car;return state.mode==='car'&&!!c&&(!!c.spec?.bike||c.spec?.width<1.2||['motorcycle','scooter','cruiser'].includes(c.style));}
function nearestNode(game,p,radius=220){let best=null,bestD=Infinity,seen=new Set();for(const seg of game.graph.index.near(p.x,p.z,radius)){for(const id of [seg.a,seg.b]){if(seen.has(id))continue;seen.add(id);const n=game.graph.nodes[id],d=dist(n,p);if(d<bestD){best=n;bestD=d;}}}return best;}
function routeFor(game,course){const a=nearestNode(game,course.start,300),b=nearestNode(game,course.end,360);if(!a||!b)return [];return roadRoute(a,b,game.graph);}
function routeLength(path){let total=0;for(let i=1;i<path.length;i++)total+=dist(path[i-1],path[i]);return total;}
function sampleRoute(path,spacing=58){if(path.length<2)return path;const out=[path[0]];let carry=0;for(let i=1;i<path.length;i++){let a={...path[i-1]},b=path[i],segment=dist(a,b);while(carry+segment>=spacing){const need=spacing-carry,t=need/Math.max(segment,.001),p={x:a.x+(b.x-a.x)*t,z:a.z+(b.z-a.z)*t};out.push(p);a=p;segment=dist(a,b);carry=0;}carry+=segment;}out.push(path.at(-1));return out;}
function lateralPoint(path,i,offset){const p=path[i],a=path[Math.max(0,i-1)],b=path[Math.min(path.length-1,i+1)],dx=b.x-a.x,dz=b.z-a.z,l=Math.hypot(dx,dz)||1;return {x:p.x-dz/l*offset,z:p.z+dx/l*offset};}
function rampAt(game,path,index){const p=path[index],a=path[Math.max(0,index-1)],b=path[Math.min(path.length-1,index+1)],yaw=Math.atan2(b.x-a.x,b.z-a.z),width=3.1,length=8.5,rise=1.55,y=game.terrain.height(p.x,p.z),topY=[y+.06,y+.06,y+rise,y+rise];return {kind:'phase3-bike-ramp',phase3Bike:true,x:p.x,z:p.z,yaw,width,length,rise,topY};}
function addRampVisual(root,r){const angle=Math.atan2(r.rise,r.length),mesh=new THREE.Mesh(new THREE.BoxGeometry(r.width,.18,r.length),mat('#b08b4b'));mesh.position.set(r.x,(r.topY[0]+r.topY[2])*.5-.04,r.z);mesh.rotation.order='YXZ';mesh.rotation.y=r.yaw;mesh.rotation.x=-angle;mesh.receiveShadow=true;root.add(mesh);}
function clearCourse(game,keepWaypoint=false){if(courseRoot){game.scene.remove(courseRoot);courseRoot.traverse(o=>{if(o.isMesh){o.geometry.dispose();if(!materialCache.has(o.material?.color?.getStyle?.())){} }});courseRoot=null;}if(game.terrain?.arcadeRamps)game.terrain.arcadeRamps=game.terrain.arcadeRamps.filter(r=>!r.phase3Bike);if(!keepWaypoint&&game.state.waypoint?.phase3Challenge){game.state.waypoint=null;game.state.route=[];}}
function buildCourse(game,course,path){clearCourse(game,true);const root=new THREE.Group();root.name='phase3-bike-course';const samples=sampleRoute(path),checks=[];
 const coneGeo=new THREE.ConeGeometry(.32,.95,7),coneMat=mat('#ff9f43'),cones=[];
 for(let i=1;i<samples.length-1;i++){const offset=(i%2?1:-1)*Math.min(2.3,1.25+i%3*.4),q=lateralPoint(samples,i,offset);checks.push({...q,name:'Slalom '+i});cones.push(q);}
 const inst=new THREE.InstancedMesh(coneGeo,coneMat,cones.length*2),dummy=new THREE.Object3D();let n=0;for(let i=0;i<cones.length;i++){const p=cones[i],a=samples[Math.max(0,i)],b=samples[Math.min(samples.length-1,i+2)],yaw=Math.atan2(b.x-a.x,b.z-a.z),nx=Math.cos(yaw),nz=-Math.sin(yaw);for(const side of [-1,1]){dummy.position.set(p.x+nx*side*2.1,game.terrain.height(p.x+nx*side*2.1,p.z+nz*side*2.1)+.48,p.z+nz*side*2.1);dummy.updateMatrix();inst.setMatrixAt(n++,dummy.matrix);}}inst.count=n;root.add(inst);
 const rampIndices=[Math.floor(samples.length*.34),Math.floor(samples.length*.68)].filter((v,i,a)=>v>1&&v<samples.length-2&&a.indexOf(v)===i),ramps=rampIndices.map(i=>rampAt(game,samples,i));for(const r of ramps)addRampVisual(root,r);game.terrain.arcadeRamps=[...(game.terrain.arcadeRamps||[]),...ramps];
 const finish=samples.at(-1);checks.push({...finish,name:'TRAGUARDO'});const y=game.terrain.height(finish.x,finish.z);box(root,'#e9e2c7',finish.x,y+2.4,finish.z,.24,4.8,.24);const banner=box(root,'#d55245',finish.x,y+4.55,finish.z,6.4,.55,.22);banner.rotation.y=Math.atan2(samples.at(-1).x-samples.at(-2).x,samples.at(-1).z-samples.at(-2).z);game.scene.add(root);courseRoot=root;return checks;
}
function setTarget(game,p,label){game.state.waypoint={x:p.x,z:p.z,name:label,phase3Challenge:true};game.state.route=roadRoute(game.state,p,game.graph);}
function startChallenge(game,course){if(!isBike(game.state)){game.toast('Serve una moto o uno scooter per il Time Attack.',4);return;}const path=routeFor(game,course);if(path.length<4){game.toast('Pista non disponibile da questa versione della rete stradale.',5);return;}const start=path[0],checks=buildCourse(game,course,path),length=routeLength(path),limit=Math.max(75,Math.min(190,length/10+42));challenge={course,path,checks,index:0,phase:'travel',startedAt:0,deadline:Infinity,limit,length};setTarget(game,start,'START · '+course.name);document.getElementById('menu')?.close();game.state.paused=false;game.toast('Raggiungi lo START in moto. Il cronometro parte quando entri nel gate.',5);}
function failChallenge(game,message){game.toast(message,5);clearCourse(game);challenge=null;}
function finishChallenge(game){const elapsed=game.state.elapsed-challenge.startedAt,newRecord=saveRecord(challenge.course.id,elapsed),name=challenge.course.name;game.toast((newRecord?'NUOVO RECORD · ':'Tempo · ')+name+' · '+formatTime(elapsed),7);clearCourse(game);challenge=null;}
function updateChallenge(game){if(!challenge)return;const s=game.state,c=challenge;if(!isBike(s)){failChallenge(game,'Time Attack annullato: devi restare in moto.');return;}if(c.phase==='travel'){if(dist(s,c.path[0])<15&&Math.abs(s.speed)<12){c.phase='running';c.startedAt=s.elapsed;c.deadline=s.elapsed+c.limit;c.index=0;setTarget(game,c.checks[0],c.checks[0].name);game.toast('VIA! Slalom, rampe e checkpoint · '+Math.round(c.limit)+' secondi.',4);}return;}if(s.elapsed>c.deadline){failChallenge(game,'Tempo scaduto. Riprova dal menu J.');return;}const target=c.checks[c.index];if(target&&dist(s,target)<10){c.index++;if(c.index>=c.checks.length){finishChallenge(game);return;}setTarget(game,c.checks[c.index],c.checks[c.index].name);game.toast('Checkpoint '+c.index+' / '+c.checks.length,1.2);}}
function paintChallengeHud(game){if(!challenge)return;queueMicrotask(()=>{if(!challenge)return;const type=document.getElementById('missionType'),title=document.getElementById('missionTitle'),desc=document.getElementById('missionDesc'),timer=document.getElementById('missionTimer');if(type)type.textContent='MOTO TIME ATTACK';if(title)title.textContent=challenge.phase==='travel'?'Raggiungi '+challenge.course.name:challenge.course.name;if(desc)desc.textContent=challenge.phase==='travel'?'Vai allo START in moto. Il tempo partirà entrando nel gate.':'Slalom + rampe · checkpoint '+Math.min(challenge.index+1,challenge.checks.length)+' / '+challenge.checks.length+' · record '+formatTime(records()[challenge.course.id]);if(timer)timer.textContent=challenge.phase==='travel'?'READY':formatTime(Math.max(0,challenge.deadline-game.state.elapsed));});}
function createStartMarkers(game){if(startRoots.length)return;for(const course of COURSES){const n=nearestNode(game,course.start,300);if(!n)continue;const root=new THREE.Group();root.userData.course=course.id;const y=game.terrain.height(n.x,n.z);for(const side of [-1,1])box(root,'#ede5cf',n.x+side*3,y+2.3,n.z,.22,4.6,.22);box(root,'#d55245',n.x,y+4.4,n.z,6.2,.5,.2);root.visible=false;game.scene.add(root);startRoots.push({root,course,point:n});}}
function updateStartMarkers(game){for(const item of startRoots)item.root.visible=dist(game.state,item.point)<720;}
function randomGoal(game,from){const candidates=[];for(const seg of game.graph.index.near(from.x,from.z,900)){if(!seg.connected||seg.road.w<6||['no','private'].includes(seg.road.access)||seg.road.k==='pedestrian')continue;for(const id of [seg.a,seg.b]){const n=game.graph.nodes[id],d=dist(n,from);if(d>420&&d<860)candidates.push(n);}}return candidates.length?candidates[Math.floor(Math.random()*candidates.length)]:null;}
function spawnStreetRacer(game){if(game.state.wanted||game.state.mission||challenge)return false;const style=Math.random()<.5?'fulmine':'zenit',p=game.findSpawn(style,170,390);if(!p)return false;const goal=randomGoal(game,p);if(!goal)return false;const path=roadRoute(p,goal,game.graph);if(path.length<4)return false;const c=game.addCar(p.x,p.z,p.yaw,false,false,style);Object.assign(c,{y:p.y,speed:18,missionUnit:true,phase3StreetRacer:true,path,pathIndex:1,stuck:0,expiresAt:game.state.elapsed+30});c.name='Auto da corsa · '+c.name;game.pose(c);streetRacer=c;return true;}
function updateStreetRacer(game,dt){nextRacerAt||=game.state.elapsed+55+Math.random()*55;if(!streetRacer){if(game.state.elapsed>=nextRacerAt){spawnStreetRacer(game);nextRacerAt=game.state.elapsed+100+Math.random()*100;}return;}const c=streetRacer;if(game.state.wanted||game.state.elapsed>c.expiresAt||dist(c,game.state)>900||!c.mesh.visible){if(c!==game.state.car)game.retire(c);streetRacer=null;return;}if(c.pathIndex>=c.path.length-1||c.stuck>5){const goal=randomGoal(game,c),path=goal&&roadRoute(c,goal,game.graph);if(path?.length>3){c.path=path;c.pathIndex=1;c.stuck=0;}else c.expiresAt=game.state.elapsed;}
 followRoad(c,dt,game.graph,game.terrain,game.collision,{max:42,accel:15,turnRate:1.65,traffic:game.cars.filter(o=>o!==c&&o!==game.state.car)});game.pose(c);}
function openCoursePicker(game){const menu=document.getElementById('menu'),title=document.getElementById('menuTitle'),content=document.getElementById('menuContent'),best=records();if(!menu||!content)return;if(title)title.textContent='Piste moto · Time Attack';content.innerHTML='<p class="about-copy">Quattro piste leggere sparse per Padova. Il record migliore viene salvato su questo browser.</p><div class="activities">'+COURSES.map((c,i)=>'<button class="activity" data-bike-course="'+i+'"><span class="icon">⚑</span><span><b>'+c.name+'</b><small>'+Math.round(dist(game.state,c.start))+' m · record '+formatTime(best[c.id])+'</small></span><span class="reward">TIME</span></button>').join('')+'</div>';content.querySelectorAll('[data-bike-course]').forEach(b=>b.onclick=()=>startChallenge(game,COURSES[Number(b.dataset.bikeCourse)]));}
function decorateActivities(){const content=document.getElementById('menuContent');if(!content||document.getElementById('phase3BikeChallenge')||!/A little extra on the side\./i.test(document.getElementById('menuTitle')?.textContent||''))return;const list=content.querySelector('.activities');if(!list)return;const b=document.createElement('button');b.id='phase3BikeChallenge';b.className='activity';b.innerHTML='<span class="icon">⚑</span><span><b>PERCORSO OSTACOLI MOTO</b><small>Slalom, rampe, salti e record personali</small></span><span class="reward">TIME</span>';b.onclick=()=>activeGame&&openCoursePicker(activeGame);list.appendChild(b);if(challenge){const cancel=document.createElement('button');cancel.className='activity';cancel.innerHTML='<span><b>ANNULLA TIME ATTACK</b><small>Interrompi il percorso moto attivo</small></span>';cancel.onclick=()=>{if(activeGame)failChallenge(activeGame,'Time Attack annullato.');document.getElementById('menu')?.close();if(activeGame)activeGame.state.paused=false;};list.appendChild(cancel);}}
new MutationObserver(decorateActivities).observe(document.getElementById('menuContent')||document.body,{childList:true,subtree:true});
const original=ModernGameplay.prototype.update;
if(!ModernGameplay.prototype.__phase3Runtime){ModernGameplay.prototype.__phase3Runtime=true;ModernGameplay.prototype.update=function(dt){original.call(this,dt);activeGame=this;createStartMarkers(this);updateStartMarkers(this);updateChallenge(this);updateStreetRacer(this,dt);paintChallengeHud(this);};}
